mapper.insert:
INSERT INTO workspaces ( uuid, external_id, organization_uuid, name, is_default, created_at, updated_at, compartment_id, display_color, data_residency, external_key_id, tags, runtime_profile_uuid ) VALUES ( #{params.UUID}, #{params.ExternalID}, #{params.OrganizationUUID}, #{params.Name}, #{params.IsDefault}, #{params.CreatedAt}, #{params.CreatedAt}, #{params.CompartmentID}, #{params.DisplayColor}, CAST(#{params.DataResidency} AS jsonb), #{params.ExternalKeyID}, CAST(#{params.Tags} AS jsonb),
#{params.RuntimeProfileUUID}
COALESCE( (SELECT default_runtime_profile_uuid FROM organizations WHERE uuid = #{params.OrganizationUUID}), '00000000-0000-4000-8000-000000000001' )
) RETURNING

mapper.select:
SELECT

FROM workspaces w
LEFT JOIN runtime_profiles rp ON rp.uuid = w.runtime_profile_uuid
WHERE w.organization_uuid = #{organizationUUID}
AND (
    (#{externalID} = 'default' AND w.is_default) OR w.external_id = #{externalID}

        OR w.uuid = #{workspaceUUID}

)

mapper.update:
UPDATE workspaces
SET name = #{params.Name},
    data_residency = CAST(#{params.DataResidency} AS jsonb),
    external_key_id = #{params.ExternalKeyID},
    tags = CAST(#{params.Tags} AS jsonb),
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND external_id = #{params.ExternalID}
RETURNING

UPDATE workspaces
SET archived_at = COALESCE(archived_at, NOW()),
    updated_at = NOW()
WHERE organization_uuid = #{organizationUUID}
AND external_id = #{externalID}
RETURNING

mapper.select:
SELECT COUNT(*)
FROM workspaces
WHERE organization_uuid = #{organizationUUID}
AND external_key_id = #{externalID}
